Let Assumptions ass: Lipschitz and ass: Random perturbation hold. Given $\rho\geq1$, let $\alpha$ and $d$ be defined in (17). Then, for any $\mathbf{x}^{0}\in(\mathbb{R}^{n})^{m}$ and $t_{0},t\geq0$,
    \begin{multline}

    \mathbb{P}\Bigg[\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t_{0}+t})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t_{0}})\leq-\frac{\alpha}{2}\sum_{k=0}^{t-1}\|\nabla\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t_{0}+k})\|^{2}\\
    +mn\alpha\sigma^{2}(t+\sqrt{t\rho}+\rho)\Bigg]\geq1-2\mathrm{e}^{-\rho},
    \end{multline}
    where $\{\mathbf{x}^{k}\}$ is generated by (10a).

Let Assumptions ass: Lipschitz and ass: Random perturbation hold. Given $\rho\geq1$, let $\alpha$ and $d$ be defined in (17). Then, for any $\mathbf{x}^{0}\in(\mathbb{R}^{n})^{m}$ and $t_{0},t\geq0$,
    \begin{multline*}
        \mathbb{P}\Big[\forall\tau\in(0,t],~\|\mathbf{x}^{t_{0}+\tau}-\mathbf{x}^{t_{0}}\|^{2}
        \leq4\alpha\tau\big(\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t_{0}})-\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{t_{0}+\tau})\big)\\
        +8mn\alpha^{2}\sigma^{2}\tau(\tau+\sqrt{\tau\rho}+\rho)\Big]\geq1-4t\mathrm{e}^{-\rho},
    \end{multline*}
    where $\{\mathbf{x}^{k}\}$ is generated by (10a).

Let Assumptions ass: Lipschitz and ass: Random perturbation hold. Given $\rho\geq1$, let $\alpha$, $d$, and $r$ be defined in (17). If $\{\mathbf{y}^{k}\}$ and $\{\mathbf{z}^{k}\}$ are coupling sequences, then
    \begin{gather}

        \mathbb{P}\Big[\mathcal{E}_{A}^{0,r}\cup\mathcal{E}_{B}^{0,r}\Big]\geq1-8r\mathrm{e}^{-\rho}.
    \end{gather}

Let Assumption ass: Random perturbation hold and let $\alpha$ be defined in (17). If $\{\mathbf{y}^{k}\}$ and $\{\mathbf{z}^{k}\}$ are coupling sequences, then for any $k\geq0$,
    \begin{gather*}
        \Delta^{k}=\Delta_{1}^{k}+\Delta_{2}^{k},
    \end{gather*}
    where $\Delta_{1}^{k}$ and $\Delta_{2}^{k}$ are defined in (34).

Let Assumption ass: Random perturbation hold and $\epsilon_{H}>0$. There exists $\rho_{\min,1}\geq1$ such that for any $\rho\geq\rho_{\min,1}$, with $\alpha$ and $r$ defined in (17), the following holds: if $\lambda_{\min}(\nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0}))<-\epsilon_{H}$ and $\{\mathbf{y}^{k}\}$ and $\{\mathbf{z}^{k}\}$ are coupling sequences, then for any $k\geq0$,
    \begin{gather*}
        \mathbb{P}\left[\|\Delta_{2}^{k}\|\leq\alpha\varsigma^{0}(k)\sqrt{2\rho}\right]\geq1-2\mathrm{e}^{-\rho},\\
        \mathbb{P}\left[\|\Delta_{2}^{r}\|\geq\frac{\alpha\varsigma^{0}(r)}{5}\right]\geq\frac{2}{3},
    \end{gather*}
    where $\varsigma^{0}(k)$ is defined in (25).

Let Assumptions ass: Lipschitz and ass: Random perturbation hold and $\epsilon_H>0$. There exists $\rho_{\min,3}\newline\geq1$ such that, for any $\rho\geq\rho_{\min,3}$, with $\alpha$, $d$, and $r$ defined in (17), the following holds. If $\lambda_{\min}(\nabla^{2}\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0}))<-\epsilon_H$ and $\{\mathbf{y}^{k}\}$ and $\{\mathbf{z}^{k}\}$ are coupling sequences, then
    \begin{gather*}
        \mathbb{P}\Big[\mathcal{E}_{A}^{0,r}\cup\mathcal{E}_{C}^{0,r}\Big]\geq1-(2r^{2}+8r)\mathrm{e}^{-\rho}.
    \end{gather*}

Let Assumptions ass: Lipschitz, ass: Coercivity, ass: Network and ass: Random perturbation hold. Further, let $f_{i}^{\star}$ denote the global minimum of function $f_{i}$ for $i\in\mathcal{V}$. Then, given parameter $\epsilon_{g} > 0$, $\epsilon_{H} = \sqrt{\epsilon_{g}L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}}$, and confidence parameter $0 < p < 1$ with $L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g},L_{\Psi_{\boldsymbol{\theta}^{0}}}^{H}$ as per (7), there exists
    \begin{gather}

        \bar{\alpha} \le \min\{\frac{1}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}},~-\frac{2\ln{(p)}}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}}\}
    \end{gather}
    such that for any step-size $\alpha \le \bar{\alpha}$, with random perturbation variance
    \begin{gather}

        \sigma^{2}=\frac{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g}\alpha\epsilon_{g}^{2}}{12mn},
    \end{gather}
    and initial condition satisfying $\bm{1}_{m}^{\top} \otimes \mathbf{I}_{n} \cdot \boldsymbol{\theta}^{0} = \bm{r}$ and $\mathbf{x}^{0} = \bm{0}$, after
    \begin{gather}

        K = \lceil \frac{\Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{0}) - \sum_{i=1}^{m} f_{i}^{\star}}{L_{\Psi_{\boldsymbol{\theta}^{0}}}^{g} \epsilon_{g}^{2} \alpha^{2}} \rceil
    \end{gather}
    iterations of (10), it follows that
    \begin{gather}

        \mathbb{P} \Bigg[\exists k \in [0,K],~\|\nabla \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})\| \le\epsilon_{g}~~\land~~\lambda_{\min} (\nabla^{2} \Psi_{\boldsymbol{\theta}^{0}}(\mathbf{x}^{k})) \ge -\epsilon_{H}
        \Bigg] \ge 1 - p.
    \end{gather}
